def skjkasdkd(lst):
    """
    You are given a list of integers.
    You need to find the largest prime value and return the sum of its digits.
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        if n < 10:
            return True
        if n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    def sum_of_digits(n):
        s = 0
        while n > 0:
            s += n % 10
            n //= 10
        return s

    max_prime = -1
    max_prime_sum = 0

    for num in lst:
        if is_prime(num):
            if num > max_prime:
                max_prime = num
                max_prime_sum = sum_of_digits(num)
            elif num == max_prime:
                max_prime_sum = max(max_prime_sum, sum_of_digits(num))

    return max_prime_sum
