from functools import cmp
import operator

def sort_array(arr):
    """
    In this Kata, you have to sort an array of non-negative integers according to
    number of ones in their binary representation in ascending order.
    For similar number of ones, sort based on decimal value.

    It must be implemented like this:
    >>> sort_array([1, 5, 2, 3, 4]) == [1, 2, 3, 4, 5]
    >>> sort_array([-2, -3, -4, -5, -6]) == [-6, -5, -4, -3, -2]
    >>> sort_array([1, 0, 2, 3, 4]) [0, 1, 2, 3, 4]
    """
    def count_ones(n):
        return bin(n).count('1')

    def compare(a, b):
        # First compare by number of ones
        if count_ones(a) < count_ones(b):
            return -1
        elif count_ones(a) > count_ones(b):
            return 1
        else:
            # If number of ones are equal, compare by decimal value
            return a - b

    # Create a key function for sorting
    def key_func(x):
        return (count_ones(x), x)

    # Sort using the key function
    return sorted(arr, key=key_func)
